import fs from 'fs';
import { createHash } from 'crypto';
import chalk from 'chalk';
import { resolveToken, retryOnAuthError } from '../core/credentials.js';
import { syncCapabilities } from '../core/capabilities.js';
import { getFiles, describeServerError } from '../api/endpoints.js';
import { replaceSnapshot, moduleToPath, listSnapshotPaths } from '../core/snapshot.js';
import { loadState, saveState } from '../core/state.js';
import { existsWd, readWd, writeWd, unlinkWd, displayPath, wdPath } from '../core/workdir.js';
import { saveStaticSnapshot, unmanagedStaticNotice } from '../core/static.js';
import { loadProjectConfig, configFileName } from '../core/project-config.js';
import { computeDiff } from '../core/file-diff.js';
import { done, skipped, info } from '../utils/logger.js';
import { confirm, closePrompts } from '../utils/prompt.js';
import { createSpinner } from '../utils/spinner.js';

// True when the file is still exactly what `init` scaffolded.
function isUntouchedScaffold(filePath, initTemplates) {
  const expected = initTemplates?.[displayPath(filePath)];
  if (!expected) return false;
  return 'sha256:' + createHash('sha256').update(fs.readFileSync(wdPath(filePath))).digest('hex') === expected;
}

/** Downloads the server state into the snapshot and the working dir. Throws on network/auth errors. */
export async function executePull(options = {}) {
  // Refresh the layout first so directories added by the server are scanned.
  await syncCapabilities();
  const token = await resolveToken();

  const spinner = createSpinner('Pulling files from the cloud...');
  spinner.start();

  let response;
  try {
    response = await getFiles(token);
    spinner.stop();
  } catch (err) {
    spinner.stop();
    console.error(chalk.red('Error: ') + describeServerError(err));
    throw err;
  }

  const canonical = response.canonical_modules || {};
  const moduleNames = Object.keys(canonical);
  const serverPaths = new Set(moduleNames.map(moduleToPath));

  // Orphans: files in the snapshot that the server no longer has and that still exist locally.
  // Computed before replaceSnapshot(), which prunes the snapshot.
  const orphans = listSnapshotPaths().filter(
    (p) => !serverPaths.has(p) && existsWd(p)
  );

  // Only the static snapshot (hashes) is refreshed; the build output is never written.
  if ('static' in response) saveStaticSnapshot(response.static);

  if (!moduleNames.length && !orphans.length) {
    info('No files in the cloud.');
    replaceSnapshot(canonical);
    if (response.revision != null) {
      const s = loadState();
      s.last_known_revision = response.revision;
      saveState(s);
    }
    noteUnmanagedStatic(response.static);
    return;
  }

  const initTemplates = loadState().init_templates;
  let pulled = 0;

  for (const moduleName of moduleNames) {
    const filePath = moduleToPath(moduleName);
    const shown = displayPath(filePath);
    const remoteContent = canonical[moduleName];

    if (existsWd(filePath)) {
      const localContent = readWd(filePath);

      if (localContent === remoteContent) {
        done(shown, 'up to date');
        continue;
      }

      // An untouched starter file is replaced without asking.
      if (!options.force && !isUntouchedScaffold(filePath, initTemplates)) {
        console.log(formatPatch(computeDiff(localContent, remoteContent, shown)));
        const overwrite = await confirm(`  Overwrite ${shown}?`);
        if (!overwrite) {
          skipped(shown, 'skipped');
          continue;
        }
      }
    }

    writeWd(filePath, remoteContent);
    done(shown, 'saved');
    pulled++;
  }

  let removed = 0;
  for (const filePath of orphans) {
    const shown = displayPath(filePath);
    if (!options.force) {
      console.log('  ' + chalk.dim('delete →') + ` ${shown}` + chalk.dim(' (removed in the cloud)'));
      const ok = await confirm(`  Delete ${shown}?`);
      if (!ok) {
        skipped(shown, 'kept');
        continue;
      }
    }
    unlinkWd(filePath);
    done(shown, 'deleted');
    removed++;
  }

  replaceSnapshot(canonical);

  if (response.revision != null) {
    const s = loadState();
    s.last_known_revision = response.revision;
    saveState(s);
  }

  const removedNote = removed ? `, deleted ${removed}` : '';
  info(`\nDone. Pulled ${pulled} file${pulled !== 1 ? 's' : ''}${removedNote}.`);
  noteUnmanagedStatic(response.static);
}

// The Mini App's files are not downloaded; say so when the project has no `static` block.
function noteUnmanagedStatic(remoteStatic) {
  if (!remoteStatic || loadProjectConfig({ tolerant: true }).static) return;
  console.log('\n' + unmanagedStaticNotice(remoteStatic, configFileName()).join('\n'));
}

function formatPatch(patch) {
  if (!patch) return '';
  return patch
    .split('\n')
    .map((line) => {
      if (line.startsWith('+') && !line.startsWith('+++')) return chalk.green(line);
      if (line.startsWith('-') && !line.startsWith('---')) return chalk.red(line);
      if (line.startsWith('@@')) return chalk.cyan(line);
      return line;
    })
    .join('\n');
}

export function registerPull(program) {
  program
    .command('pull')
    .description('Download cloud state into working directory and local snapshot')
    .option('--force', 'Overwrite local files without confirmation')
    .action(async (options) => {
      try {
        await retryOnAuthError(() => executePull(options));
      } catch {
        process.exit(1);
      } finally {
        closePrompts();
      }
    });
}
